import { exportMonthlyReport } from './excel';
import * as ExcelJS from 'exceljs';
import { saveAs } from 'file-saver';
import { DailyReport } from '../types';

jest.mock('exceljs');
jest.mock('file-saver');

describe('exportMonthlyReport', () => {
  const mockReports: DailyReport[] = [
    {
      id: '1',
      site_id: 'site1',
      machine_id: 'machine1',
      technician_id: 'tech1',
      report_date: '2026-07-15',
      sample_count: 10,
      evk_status: 'verified',
    },
    {
      id: '2',
      site_id: 'site1',
      machine_id: 'machine1',
      technician_id: 'tech2',
      report_date: '2026-07-16',
      sample_count: 5,
      evk_status: 'failed',
    },
  ];

  const mockMachines = [
    { id: 'machine1', serial_number: 'SN1', model: 'IONSCAN 500DT' },
    { id: 'machine2', serial_number: 'SN2', model: 'Itemiser 4DX' },
  ];

  it('creates worksheet with correct month/year name', async () => {
    const mockWorksheet = { addRow: jest.fn(), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7);

    expect(mockWorkbook.addWorksheet).toHaveBeenCalledWith('July 2026');
  });

  it('builds correct header with days in month', async () => {
    const mockHeaderRow = { eachCell: jest.fn() };
    const mockWorksheet = { addRow: jest.fn().mockReturnValue(mockHeaderRow), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7); // July has 31 days

    expect(mockHeaderRow.eachCell).toHaveBeenCalled();
    // Verify header length: 2 (machine/model) + 31 (days) + 4 (summary) = 37 columns
  });

  it('populates machine data correctly', async () => {
    const mockRow = {
      getCell: jest.fn().mockImplementation((col) => {
        const cell = { font: {}, alignment: {}, fill: {} };
        // Return specific values for machine/model columns
        if (col === 1) cell.value = 'SN1';
        if (col === 2) cell.value = 'IONSCAN 500DT';
        return cell;
      }),
    };
    const mockWorksheet = { addRow: jest.fn().mockReturnValue(mockRow), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7);

    expect(mockWorksheet.addRow).toHaveBeenCalledWith(
      expect.arrayContaining(['SN1', 'IONSCAN 500DT', /* day values */, 15, 1, 0, 0])
    );
  });

  it('calculates summary columns correctly', async () => {
    const mockRow = {
      getCell: jest.fn().mockImplementation((col) => {
        const cell = { value: 0 };
        // Return summary values for last 4 columns
        if (col === 35) cell.value = 15; // Total
        if (col === 36) cell.value = 1;  // Verified
        if (col === 37) cell.value = 1;  // Failed
        if (col === 38) cell.value = 0;  // Bypass
        return cell;
      }),
    };
    const mockWorksheet = { addRow: jest.fn().mockReturnValue(mockRow), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7);

    // Verify summary calculations
    expect(mockRow.getCell(35).value).toBe(15); // 10 + 5
    expect(mockRow.getCell(36).value).toBe(1);   // 1 verified
    expect(mockRow.getCell(37).value).toBe(1);   // 1 failed
    expect(mockRow.getCell(38).value).toBe(0);   // 0 bypass
  });

  it('styles day cells based on EVK status', async () => {
    const mockDayCell = {
      fill: {},
      font: {},
      alignment: {},
    };
    const mockRow = {
      getCell: jest.fn().mockImplementation((col) => {
        // Day columns start at index 3 (0-based: 2)
        if (col >= 3 && col <= 33) return mockDayCell;
        return { value: '' };
      }),
    };
    const mockWorksheet = { addRow: jest.fn().mockReturnValue(mockRow), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7);

    // Verify styling for day 15 (verified) and day 16 (failed)
    expect(mockDayCell.fill).toMatchObject({
      type: 'pattern',
      pattern: 'solid',
    });
    // Add more specific assertions for each status
  });

  it('handles missing machine data gracefully', async () => {
    const mockReportsWithGap = [
      {
        id: '1',
        site_id: 'site1',
        machine_id: 'machine1',
        technician_id: 'tech1',
        report_date: '2026-07-15',
        sample_count: 10,
        evk_status: 'verified',
      },
      // No report for machine2
    ];

    const mockRow = {
      getCell: jest.fn().mockImplementation((col) => {
        const cell = { value: '' };
        if (col === 1) cell.value = 'SN1';
        if (col === 2) cell.value = 'IONSCAN 500DT';
        return cell;
      }),
    };
    const mockWorksheet = { addRow: jest.fn().mockReturnValue(mockRow), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport(mockReportsWithGap, mockMachines, 2026, 7);

    // Machine2 row should have empty day values
    expect(mockWorksheet.addRow).toHaveBeenCalledWith(
      expect.arrayContaining(['SN2', 'Itemiser 4DX', /* empty day values */, 0, 0, 0, 0])
    );
  });

  it('handles February leap year correctly', async () => {
    const mockWorksheet = { addRow: jest.fn(), columns: [] };
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue(mockWorksheet),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbox as jest.Mock).mockImplementation(() => mockWorkbook as any);

    await exportMonthlyReport([], mockMachines, 2024, 2); // 2024 is leap year

    // Verify header has 29 days (2/1-2/29) + 2 machine/model + 4 summary = 35 columns
    expect(mockWorksheet.addRow).toHaveBeenCalledWith(
      expect.arrayContaining([/* 29 day headers */])
    );
  });

  it('saves file with correct default name', async () => {
    const mockWorkbook = {
      addWorksheet: jest.fn().mockReturnValue({ addRow: jest.fn(), columns: [] }),
      xlsx: { writeBuffer: jest.fn().mockResolvedValue(Buffer.from([])) },
    };
    (ExcelJS.Workbook as jest.Mock).mockImplementation(() => mockWorkbook as any);
    (saveAs as jest.Mock).mockImplementation(() => {});

    await exportMonthlyReport(mockReports, mockMachines, 2026, 7);

    expect(saveAs).toHaveBeenCalledWith(
      expect.any(Blob),
      'July 2026 2026.xlsx' // Default format: "Month Year year.xlsx"
    );
  });
});
